/*
 * This file is run in a ServiceWorker context.
 * Workbox (via GenerateSW) handles precaching and runtime caching automatically.
 * This file lets us add custom logic on top.
 */

/// <reference lib="webworker" />
declare const self: ServiceWorkerGlobalScope;

import { clientsClaim } from 'workbox-core';
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';

// Take control immediately on install (skip waiting)
self.skipWaiting();
clientsClaim();

// Clean up old caches from previous versions
cleanupOutdatedCaches();

// Precache all assets generated by the build
precacheAndRoute(self.__WB_MANIFEST);

// Let PowerSync WebSocket and API calls pass through — don't cache them
// Workbox GenerateSW handles this via navigateFallback + runtimeCaching config
